 const setList=[...(setsData.sets||[])].sort((a,b)=>(b.claimable-a.claimable)||(a.claimed-b.claimed)||(b.owned/b.total-a.owned/a.total)).map(setCard);
 const setSection=setList.length?'<section class="section vault-missions-section set-section"><div class="section-head vault-section-head"><div><p class="eyebrow">SETS THÉMATIQUES</p><h2>RÉUNIS LES CARTES</h2></div><p>Possède toutes les cartes d’un set pour gagner une récompense unique. Récompenses de sets : '+money(setsData.dailyCap)+' FC maximum par jour (il te reste '+money(setsData.remainingToday)+' FC aujourd’hui).</p></div><div class="mission-grid vault-mission-grid">'+setList.join('')+'</div></section>':'';
